#' Differential Isoform Usage Between Groups of Cells
#'
#' Tests, for each gene, whether the usage of its isoforms (fraction of the gene counts) differs between
#' groups of cells of an iDGE Seurat object generated by SCALPEL, with the same method as the
#' nf-core/scalpel pipeline (\code{differential/DIU_table.csv}).
#'
#' @param seurat_obj Seurat object with isoform counts (features \code{gene***isoform}), e.g.
#'   \code{<outdir>/differential/iDGE_seurat.RDS}. Counts split in several layers (one per sample) are joined.
#' @param group_by Metadata column with the groups of cells to compare (2 groups: group1 vs group2;
#'   more than 2 groups: each group vs the rest).
#' @param sample_by Metadata column with the sample of each cell (default \code{"orig.ident"}), used to
#'   permute the cells within samples (\code{test = "permutation"}) and to assess the replication of the
#'   changes in each sample. \code{NULL}: not used. Ignored if equal to \code{group_by}.
#' @param assay Seurat assay. Default \code{"RNA"}.
#' @param isoform_annotation Isoform 3' ends: the SCALPEL isoform annotation (directory
#'   \code{<outdir>/isoform} or \code{*.annots.gz} files, recommended) or a GTF \code{GRanges}
#'   (e.g. \code{rtracklayer::import("annotation.gtf")}). \code{NULL}: no event type / direction.
#' @param test \code{"chisq"} (X2 test on the counts aggregated per group, original SCALPEL) or
#'   \code{"permutation"} (same X2 statistic, p-value from permutations of the cells between the compared
#'   groups, within samples: accounts for the cell-to-cell variability of the isoform usage).
#' @param threshold_pval Adjusted p-value threshold. Default 0.05.
#' @param threshold_abund Isoforms below this fraction of the gene counts in both groups are not tested
#'   (\code{thr.abund}). Default 0.05.
#' @param threshold_var Minimal isoform usage change between groups (\code{thr.var}, \code{max_delta_PU}).
#'   Default 0.1.
#' @param n_perm Maximal number of permutations per gene (\code{test = "permutation"}). Default 10000.
#' @param cores Number of cores. Default 1.
#' @param seed Random seed (permutations). Default 1.
#' @param extended \code{FALSE} (default): isoforms of the genes with a differential isoform usage only
#'   (adjusted p-value < \code{threshold_pval}, \code{max_delta_PU >= threshold_var}, change not
#'   contradicted between samples). \code{TRUE}: all tested genes.
#'
#' @details
#' Isoform counts are aggregated per group; isoforms below \code{threshold_abund} in both groups are not
#' tested, and genes are tested when at least 2 isoforms remain and all expected counts are >= 5. The
#' p-values are adjusted (Benjamini-Hochberg) once per gene and comparison.
#'
#' Each gene is classified as \code{tandem_3UTR} (the tested isoforms share their terminal exon: alternative
#' polyadenylation in the same last exon) or \code{alternative_terminal_exon}. For tandem events,
#' \code{delta_3end} is the change of the weighted 3' UTR length of group1 vs group2 (nt) and
#' \code{direction} is \code{shortening} or \code{lengthening}.
#'
#' With \code{sample_by}, the change of the most changing isoform of each gene is measured in each sample
#' (samples with >= 20 UMIs of the gene in both groups): \code{replicated} is TRUE when it has the same sign
#' and at least half of \code{threshold_var} in every evaluable sample (NA if fewer than 2 samples).
#'
#' @return A \code{data.table} with one row per isoform and comparison: gene and isoform, comparison
#'   (\code{comparison}, \code{group1}, \code{group2}), \code{event_type}, \code{direction},
#'   \code{delta_3end}, isoform counts (\code{counts.group1/2}), usage (\code{PU.group1/2}) and change
#'   (\code{delta_PU}), gene \code{p.value.adjusted}, \code{p.value}, \code{statistic},
#'   \code{max_delta_PU}, replication (\code{replicated}, \code{delta_PU_by_sample}, ...), dominant
#'   isoforms, 3' ends and filters, as the pipeline \code{DIU_table.csv}.
#'
#' @examples
#' \dontrun{
#' idge = readRDS("results/differential/iDGE_seurat.RDS")
#' idge$celltype = ...
#' diu = FindIsoforms(idge, group_by = "celltype", isoform_annotation = "results/isoform",
#'                    test = "permutation", cores = 8)
#' }
#'
#' @export
FindIsoforms <- function(
    seurat_obj,
    group_by,
    sample_by = "orig.ident",
    assay = "RNA",
    isoform_annotation = NULL,
    test = "chisq",
    threshold_pval = 0.05,
    threshold_abund = 0.05,
    threshold_var = 0.1,
    n_perm = 10000,
    cores = 1,
    seed = 1,
    extended = FALSE) {
  # checks
  meta <- seurat_obj[[]]
  if (!(group_by %in% colnames(meta))) stop("Error: ", group_by, " not found in Seurat object !")
  if (!is.null(sample_by) && (!(sample_by %in% colnames(meta)) || sample_by == group_by)) sample_by <- NULL

  #- counts (layers joined) & groups of cells...
  seurat_obj <- SeuratObject::JoinLayers(seurat_obj, assay = assay)
  counts <- SeuratObject::LayerData(seurat_obj, assay = assay, layer = "counts")
  groups <- as.character(seurat_obj[[]][[group_by]])
  cells <- which(!is.na(groups))
  strata <- if (is.null(sample_by)) NULL else as.character(seurat_obj[[]][[sample_by]])[cells]

  #- isoform 3' ends...
  ends <- .isoform_ends(isoform_annotation)

  res <- .diu_engine(
    counts = counts[, cells, drop = FALSE], groups = groups[cells], strata = strata, ends = ends, test = test,
    threshold_pval = threshold_pval, threshold_abund = threshold_abund, threshold_var = threshold_var,
    n_perm = n_perm, cores = cores, seed = seed
  )
  if (!("significant" %in% colnames(res))) return(res)

  #- genes with a differential isoform usage (all isoforms of these genes)...
  if (!extended) res <- res[significant == TRUE]
  res[, significant := NULL]
  return(res[])
}

# Isoform 3' ends from the SCALPEL isoform annotation (directory / annots.gz files) or a GTF GRanges
.isoform_ends <- function(isoform_annotation) {
  if (is.null(isoform_annotation)) return(NULL)
  if (is.character(isoform_annotation)) {
    files <- unlist(lapply(isoform_annotation, function(x) {
      if (dir.exists(x)) list.files(x, pattern = "annots.gz$", full.names = TRUE) else x
    }))
    if (length(files) == 0) stop("No *.annots.gz file found in ", paste(isoform_annotation, collapse = ", "))
    return(.Read_isoformEnds(files))
  }
  if (methods::is(isoform_annotation, "GRanges")) {
    #- terminal exon of each transcript: most downstream exon (+: largest end, -: smallest start)...
    ex <- data.table::as.data.table(isoform_annotation[isoform_annotation$type == "exon"])
    ex <- ex[, list(start, end, strand = as.character(strand), gene_name, transcript_name)]
    ex[, o := ifelse(strand == "+", end, -start)]
    te <- ex[order(-o)][, .SD[1], by = c("gene_name", "transcript_name")]
    te[, `:=`(three_end = ifelse(strand == "+", end, start), te5 = ifelse(strand == "+", start, end))]
    te[, `:=`(gene_name = gsub("_", "-", gene_name), transcript_name = gsub("_", "-", transcript_name))]
    return(unique(te[, list(gene_name, transcript_name, strand, three_end, te5)], by = c("gene_name", "transcript_name")))
  }
  stop("isoform_annotation: SCALPEL isoform directory / annots.gz files, or a GTF GRanges")
}
